            this.rfc3339Formatter = new SimpleDateFormat("yyyy-MM-dd");
        }
        this.serializeTime = serializeTime;
        this.threeDigitMillis = threeDigitMillis;
        this.rfc3339Formatter.setTimeZone(serializationTimezone);
